+	cwd, err := os.Getwd()
+	if err != nil {
+		t.Fatalf("failed to get cwd: %v", err)
+	}
+	home := os.Getenv("HOME")
+
+	agent := newMockAgent()
+
+	tests := []struct {
+		skip       func() bool
+		name       string
+		customPath string
+		want       string
+		userFlag   bool
+		wantErr    bool
